          id = ids[i]
          gsub(/''^[[:space:]]+|[[:space:]]+$/, "", id)
          if (id ~ /'"\\|/) {
            split(id, parts, /\\|/)
            id = parts[2]
          }
          if (id "'!= "") print pep "'"\\t\" id
